BEGIN;
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (3287, 'a.yml', 'DEFAULT_GROUP', 'a=abc', '1c8128107bd726f312947b043e28572a', '2026-02-28 07:44:31', '2026-02-28 07:45:11', 'nacos', '172.18.0.1', '', '75bc1675-1e8e-4099-b2f2-d9482ce14f4e', '', '', '', 'properties', '', '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (5550, 'boot-datasource.yml', 'DEFAULT_GROUP', 'spring:\n  datasource:\n    type: com.zaxxer.hikari.HikariDataSource\n    driver-class-name: com.mysql.cj.jdbc.Driver\n    url: jdbc:mysql://${application-datasource-jdbc-url:maozi-cloud-basic-mysql:3306}/${application-datasource-db-name:${spring.application.name}-${application.environment}-db}?useSSL=false&serverTimezone=Asia/Shanghai&characterEncoding=utf8&nullCatalogMeansCurrent=true\n    username: ${application-datasource-jdbc-username:root}\n    password: ${application-datasource-jdbc-password:password}\n    hikari:\n      # 最大连接，根据业务压测调整，默认推荐10~20，不要直接50\n      maximum-pool-size: 15\n      # 获取连接等待超时时间\n      connection-timeout: 6000\n      # 不配置minimum-idle，Hikari官方推荐，最小空闲连接等于最大连接\n      # minimum-idle: 10\n      # 空闲连接超时，注意必须小于max-lifetime\n      idle-timeout: 300000\n      # 连接最大存活时间，比mysql wait_timeout小至少60s，示例540s=9min\n      max-lifetime: 540000\n      # 删掉 connection-test-query，Hikari用JDBC4 isValid校验', '7cc45b7052b60a30606688ac3bc0c231', '2026-07-03 13:54:34', '2026-10-03 07:22:25', NULL, '192.168.65.1', '', 'local', '', '', '', 'yaml', '', '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (5551, 'boot-elasticsearch.yml', 'DEFAULT_GROUP', 'spring:\n  data:\n    elasticsearch:\n    ####集群名称\n     cluster-name: maozi-cloud-es\n    ####地址 \n     cluster-nodes: 192.168.0.1,192.168.0.2', '488145c960b14d62df086865f533cc4a', '2026-07-03 13:54:34', '2026-07-03 13:54:34', NULL, '172.18.0.1', '', 'local', NULL, NULL, NULL, 'yaml', NULL, '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (5553, 'boot-redis.yml', 'DEFAULT_GROUP', 'spring:\n  data:\n    redis:\n      host: ${APPLICATION_REDIS_SERVER:maozi-cloud-basic-redis}\n      port: ${APPLICATION_REDIS_PORT:6379}\n      # 密码从环境变量读取，禁止硬编码\n      password: ${APPLICATION_REDIS_SERVER_PASSWORD:password}\n      database: ${APPLICATION_REDIS_SERVER_DATABASE:0}\n      # 可选，客户端标识，方便redis client list排查\n      client-name: ${spring.application.name}\n      lettuce:\n        # 命令超时，建议500ms，根据业务微调，不要超过1s\n        timeout: 500ms\n        shutdown-timeout: 300ms\n        pool:\n          # 最大活跃连接，根据单实例QPS，一般80~200\n          max-active: 120\n          # 获取连接最大等待时间1s\n          max-wait: 1000ms\n          max-idle: 60\n          # 维持少量预热连接\n          min-idle: 10', '605e5296aff327c8ec986fc9b73888b8', '2026-07-03 13:54:34', '2026-10-03 04:31:47', NULL, '172.18.0.1', '', 'local', '', '', '', 'yaml', '', '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (5575, 'cloud-default.yml', 'DEFAULT_GROUP', 'server:\n  port: ${APPLICATION_PORT:${application.port:0}}\n  error.path: /application/error\n  # graceful=优雅停机 / immediate=立刻关闭\n  shutdown: graceful\n  undertow:\n    # 单个请求超时时间，单位毫秒\n    request-timeout: 30000\n  # compression:\n  #   enabled: true\n  #   min-response-size: 1024\n  #   mime-types: application/json,application/xml,text/html,text/xml,text/plain\n\nspring:\n  lifecycle:\n    # 优雅停机等待最大超时时间，按需调整，一般10~30s\n    timeout-per-shutdown-phase: 65s\n  main:\n    banner-mode: off\n    log-startup-info: false\n  web:\n    resources:\n      add-mappings: false\n  mvc: \n    throw-exception-if-no-handler-found: true\n    pathmatch.matching-strategy: ant_path_matcher\n  jackson: \n    time-zone: GMT+8\n    date-format: yyyy-MM-dd HH:mm:ss\n    default-property-inclusion: NON_NULL\n\nfeign:\n  sentinel:\n    enabled: true\n  okhttp:\n    enabled: true\n  httpclient:\n    enabled: false\n  client:\n    config:\n      default:\n        connectTimeout: 30000\n        readTimeout: 30000\n  compression:\n    request:\n      # 开启请求数据的压缩功能\n      enabled: true\n      # 最小压缩值标准，当数据大于 1024 才会进行压缩\n      min-request-size: 1024\n      # 压缩类型\n      mime-types: text/xml,application/xml,application/json\n    response:\n      enabled: true\n\nlogging: \n  level: \n    root: ERROR\n    com.maozi: INFO\n    org.apache.dubbo.registry: OFF\n    org.apache.dubbo.remoting: OFF', '182d08f87932cd8e502a511da843ede1', '2026-07-03 13:54:34', '2026-09-29 14:31:02', NULL, '172.18.0.1', '', 'local', '', '', '', 'yaml', '', '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (5576, 'cloud-dubbo.yml', 'DEFAULT_GROUP', 'dubbo:\n  application: \n    name: dubbo-${spring.application.name}\n    # instance/interface/all\n    register-mode: instance\n    version: ${application.version:main}\n    serialize-check-status: DISABLE\n    check-serializable: false\n  scan:\n    base-packages: com.maozi.${application-project-abbreviation}.*.api.impl.rpc\n  protocol:\n    # name: tri\n    name: dubbo\n    port: ${APPLICATION_DUBBO_PORT:${application.dubbo.port:-1}}\n  provider:\n    timeout: 6000\n    filter: applicationDubboContextLoadFilter\n    prefer-serialization: hessian2\n    serialization: hessian2\n  consumer:\n    check: false\n    timeout: 6000\n    retries: 1\n    filter: applicationDubboContextTransmitFilter\n  registry:\n    address: nacos://${spring.cloud.nacos.discovery.server-addr}?namespace=${spring.cloud.nacos.discovery.namespace}', '5a68ec334d732b25fab746dcf560b7fa', '2026-07-03 13:54:34', '2026-10-17 15:10:00', NULL, '172.18.0.1', '', 'local', '', '', '', 'yaml', '', '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (5577, 'cloud-nacos.yml', 'DEFAULT_GROUP', 'spring: \n  cloud: \n    nacos: \n      discovery:\n        enabled: true\n        register-enabled: true\n        metadata: \n          version: ${application.version:main}', 'fd1de2e137ce9e9b7f35977c32d444fd', '2026-07-03 13:54:34', '2026-09-07 11:17:35', 'nacos', '192.168.65.1', '', 'local', '', '', '', 'yaml', '', '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (5578, 'cloud-rocket.yml', 'DEFAULT_GROUP', 'spring:\n  cloud:\n    stream:\n      rocketmq:\n        binder:\n          # access-key: \n          # secret-key: \n          name-server: localhost:9876\n# rocketmq:\n  # instance:\n    # id: \n    # name: ', 'e01da9f5d2b141a256fb4baa9e8c32b3', '2026-07-03 13:54:34', '2026-07-03 13:54:34', NULL, '172.18.0.1', '', 'local', '', NULL, NULL, 'yaml', NULL, '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (5579, 'cloud-sentinel.yml', 'DEFAULT_GROUP', 'resttemplate:\n  sentinel:\n    enabled: true\n\nfeign:\n  sentinel: \n    enabled: true\n\nspring: \n  cloud: \n    sentinel:\n      name: ${spring.application.name}-${application.environment:local}-${application.version:main}\n      eager: true\n      transport:\n        port: 8719\n        dashboard: ${APPLICATION_SENTINEL_SERVER:maozi-cloud-basic-sentinel:8858}\n      http-method-specify: true\n      datasource:\n        flow:\n          nacos:\n            server-addr: ${spring.cloud.nacos.config.server-addr}\n            namespace: middleware\n            groupId: SENTINEL_GROUP\n            dataId: ${spring.cloud.sentinel.name}-flow-rules.json\n            rule-type: flow\n        degrade:\n          nacos:\n            server-addr: ${spring.cloud.nacos.config.server-addr}\n            namespace: middleware\n            groupId: SENTINEL_GROUP\n            dataId: ${spring.cloud.sentinel.name}-degrade-rules.json\n            rule-type: degrade\n        param-flow:\n          nacos:\n            server-addr: ${spring.cloud.nacos.config.server-addr}\n            namespace: middleware\n            groupId: SENTINEL_GROUP\n            dataId: ${spring.cloud.sentinel.name}-param-rules.json\n            rule-type: param-flow\n        system:\n          nacos:\n            server-addr: ${spring.cloud.nacos.config.server-addr}\n            namespace: middleware\n            groupId: SENTINEL_GROUP\n            dataId: ${spring.cloud.sentinel.name}-system-rules.json\n            rule-type: system\n        authority:\n          nacos:\n            server-addr: ${spring.cloud.nacos.config.server-addr}\n            namespace: middleware\n            groupId: SENTINEL_GROUP\n            data-id: ${spring.cloud.sentinel.name}-authority-rules.json\n            rule-type: authority', '334c7c3b92af00bdd2fa0b1dd5267d5b', '2026-07-03 13:54:34', '2026-10-17 14:54:08', NULL, '172.18.0.1', '', 'local', '', '', '', 'yaml', '', '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (5641, 'saas-param-error.json', 'DEFAULT_GROUP', '{\n    \"orderId\":\"订单\",\n    \"memberId\":\"客户\",\n    \"promoteId\":\"推广\",\n    \"day\":\"天数\",\n    \"labelId\":\"标签\",\n    \"userId\":\"用户\",\n    \"username\":\"用户名\",\n    \"password\":\"密码\",\n    \"messageId\":\"消息\",\n    \"roleId\":\"角色\",\n    \"compareCredentialsImage\":\"比价凭证\",\n    \"orderValuationId\":\"报价单\",\n    \"assessorAmount\":\"报价价格\",\n    \"storesId\":\"门店\",\n    \"city\":\"城市\",\n    \"query\":\"关键字\",\n    \"region\":\"城市\"\n}', '57ddd9c3a95d95c80023360aa916a225', '2026-07-03 13:54:34', '2026-07-03 13:54:34', NULL, '172.18.0.1', '', 'local', NULL, NULL, NULL, 'json', NULL, '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (5642, 'boot-arthas.yml', 'DEFAULT_GROUP', 'arthas: \n  agent-id: ${spring.application.name}\n  tunnel-server: ws://localhost:7777/ws\n  telnet-port: -1\n  http-port: -1', '643c917b51311cefa55fb225a7b0cb2b', '2026-07-03 13:54:34', '2026-07-03 13:54:34', NULL, '172.18.0.1', '', 'local', '', NULL, NULL, 'yaml', NULL, '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (5643, 'boot-lock.yml', 'DEFAULT_GROUP', 'lock:\n  redisson:\n    address: redis://${spring.data.redis.host}:${spring.data.redis.port}\n    password: ${spring.data.redis.password}\n    database: ${spring.data.redis.database:0}\n    # waitTime: 60 #获取锁最长阻塞时间（默认：60，单位：秒）\n    # leaseTime: 60 #已获取锁后自动释放时间（默认：60，单位：秒）\n    # redis集群配置 如 redis://127.0.0.1:7000,redis://127.0.0.1:7001,redis://127.0.0.1:7002\n    # spring.klock.address 和 spring.klock.cluster-server.node-addresses 选其一即可\n    # cluster-server.node-addresses:', 'd037294dcbda68b36486a37f57f7d1ef', '2026-07-03 13:54:34', '2026-07-15 15:47:31', 'nacos', '172.18.0.1', '', 'local', '', '', '', 'yaml', '', '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (5644, 'boot-monitor.yml', 'DEFAULT_GROUP', 'spring:  \n  boot: \n    admin: \n      client:\n        url: http://${APPLICATION_MONITOR_SERVER:maozi-cloud-basic-monitor:2000}\n        username: admin\n        password: admin\n        auto-deregistration: true\n        instance: \n          prefer-ip: true\n          metadata: \n            version: 环境:${application.environment:local} 版本:${application.version:main}\n            tags: \n              environment: ${application.environment:local}\n              version: ${application.version:main}\n\nendpoints:\n  dubbo:\n    enabled: true\n\nmanagement:\n  info.env.enabled: true\n  health:\n    dubbo:\n      status:\n        defaults: memory\n        extras: load,threadpool\n  endpoints:\n    web:\n      exposure:\n        include: \'*\'\n  endpoint:\n    serviceregistry:\n      enabled: true\n    shutdown:\n      enabled: true\n    dubbo:\n      enabled: true\n    dubbo-shutdown:\n      enabled: true\n    dubbo-configs:\n      enabled: true\n    dubbo-services:\n      enabled: true\n    dubbo-references:\n      enabled: true\n    dubbo-properties:\n      enabled: true\n    health:\n      show-details: ALWAYS\n      probes.enabled: true\n  metrics:\n    tags:\n      application: ${spring.application.name}\n      instances: ${spring.cloud.client.ip-address}\n      environment: ${application.environment}\n    distribution:\n      percentiles-histogram:\n        http:\n          server:\n            requests: \'true\'\n  observations: \n    key-values: \n      application: ${spring.application.name}\n      instances: ${spring.cloud.client.ip-address}\n      environment: ${application.environment}', 'c31c3a146c6d3b31f5fc48bf121a8ed4', '2026-07-03 13:54:34', '2026-10-17 05:03:54', NULL, '172.18.0.1', '', 'local', '', '', '', 'yaml', '', '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (5645, 'cloud-oauth.yml', 'DEFAULT_GROUP', 'spring:\n  security:\n    oauth2:\n      resourceserver:\n        opaquetoken:\n          # http 或 rpc\n          # mode: http\n          # 客户端id\n          client-id: system\n          # 客户端秘钥\n          client-secret: 123456', '77e5f1492fd39d65cead251a27a4abea', '2026-07-03 13:54:34', '2026-07-08 20:20:30', 'nacos', '172.18.0.1', '', 'local', '', '', '', 'yaml', '', '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (5646, 'boot-db.yml', 'DEFAULT_GROUP', 'mybatis-plus:\n  mapper-locations: classpath:com/maozi/${application-project-abbreviation}/*/mapper/*.xml\n  # typeEnumsPackage: com.maozi.${application-project-abbreviation}.*.enums\n  configuration: \n    map-underscore-to-camel-case: true\n    log-impl: com.maozi.db.config.MybatisPlusLog\n    default-enum-type-handler: com.baomidou.mybatisplus.core.handlers.MybatisEnumTypeHandler\n    # log-impl: org.apache.ibatis.logging.stdout.StdOutImpl\n  global-config: \n    refresh: false\n    banner: false\n    db-config:\n      db-type: mysql\n      id-type: AUTO\n      field-strategy: NOT_NULL\n      column-like: false\n      capital-mode: true\n      logic-delete-value: 1\n      logic-not-delete-value: 0\n\nmybatis-plus-join:\n  banner: false\n  table-alias: main\n\nmybatis:\n  configuration:\n    cache-enabled: false\n\nspring: \n  flyway: \n    enabled: true\n    table: system_table_flyway\n    clean-disabled: true\n    out-of-order: true\n    baseline-on-migrate: true\n    baseline-version: 0\n    locations: classpath:db\n    encoding: UTF-8', '6b82a3996631502d935dd3831737dd42', '2026-07-03 13:54:34', '2026-07-03 13:54:34', NULL, '172.18.0.1', '', 'local', '', NULL, NULL, 'yaml', NULL, '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (5647, 'maozi-cloud-system-service.yml', 'DEFAULT_GROUP', 'application:\n  title: 系统服务\n  details: 管理 用户、角色、权限、系统配置 等功能\n\n# application-datasource-jdbc-url: localhost:3306/maozi-cloud-test-db\n# application-datasource-jdbc-username: root\n# application-datasource-jdbc-password: password\n# application-datasource-db-name: maozi-cloud-system-local-db\n\napplication-project-whitelist: /config/system/get\n\napplication-project-system: \n  projectName: 小猫子脚手架\n  corporationName: 小猫子网络科技有限公司\n  icon: http://dummyimage.com/100x100\n  environment: ${application.environment}\n  description: 基于 Spring Cloud Alibaba + Dubbo 的一站式分布式解决方案开源封装，内置分布式应用开发所需全套组件，统一团队代码风格，保障代码质量，让开发者专注业务逻辑，实现高效快速开发。\n  copyright: 本网站所有权归《${application-project-system.corporationName}》所有，请勿抄袭和抄袭\n\nspring.servlet.multipart: \n  # 上传大小限制（默认仅 1MB）\n  max-file-size: 1MB\n  \noss:\n  # 路由到阿里云处理器\n  store-type: aliyun\n  aliyun:\n    access-key-id: ${APPLICATION_ALIYUN_CLIENT_ID}\n    access-key-secret: ${APPLICATION_ALIYUN_CLIENT_SECRET}\n    region: cn-beijing\n    endpoint: https://oss-cn-beijing.aliyuncs.com\n    bucket: maozi-cloud-bucket\n    #domain:                  # 可选，CDN 自定义域名', 'ce0f100dfda60a585b3e9d03a4a79733', '2026-07-03 13:54:34', '2026-09-19 21:02:50', 'nacos', '192.168.65.1', '', 'local', '', '', '', 'yaml', '', '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (5648, 'maozi-cloud-oauth-service.yml', 'DEFAULT_GROUP', 'application:\n  title: 认证授权服务\n  details: 管理 三方认证授权、客户端 等功能\n\n# application-datasource-jdbc-url: localhost:3306/maozi-cloud-test-db\n# application-datasource-jdbc-username: root\n# application-datasource-jdbc-password: password\n\napplication-datasource-db-name: maozi-cloud-oauth-local-db\n\n# application-project-whitelist: ', 'c53dbfd094a9a9719c44ea97767ed6dd', '2026-07-03 13:54:34', '2026-09-07 09:51:28', 'nacos', '192.168.65.1', '', 'local', '', '', '', 'yaml', '', '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (5649, 'maozi-cloud-gateway-service.yml', 'DEFAULT_GROUP', 'application:\n  port: 1100\n  title: 网关服务\n  details: 处理 流量分发、黑白名单、流控 等功能\n\nspring: \n  cloud:\n    sentinel:\n      name: ${spring.application.name}-${application.environment:local}-${application.version:main}\n      eager: true\n      transport:\n        port: 8719\n        dashboard: ${APPLICATION_SENTINEL_SERVER:maozi-cloud-basic-sentinel:8858}\n      filter:\n        enabled: false\n      datasource:\n        flow:\n          nacos:\n            server-addr: ${spring.cloud.nacos.config.server-addr}\n            namespace: middleware\n            groupId: SENTINEL_GROUP\n            dataId: ${spring.cloud.sentinel.name}-flow-rules.json\n            rule-type: flow\n        degrade:\n          nacos:\n            server-addr: ${spring.cloud.nacos.config.server-addr}\n            namespace: middleware\n            groupId: SENTINEL_GROUP\n            dataId: ${spring.cloud.sentinel.name}-degrade-rules.json\n            rule-type: degrade\n        param-flow:\n          nacos:\n            server-addr: ${spring.cloud.nacos.config.server-addr}\n            namespace: middleware\n            groupId: SENTINEL_GROUP\n            dataId: ${spring.cloud.sentinel.name}-param-rules.json\n            rule-type: param-flow\n        system:\n          nacos:\n            server-addr: ${spring.cloud.nacos.config.server-addr}\n            namespace: middleware\n            groupId: SENTINEL_GROUP\n            dataId: ${spring.cloud.sentinel.name}-system-rules.json\n            rule-type: system\n        authority:\n          nacos:\n            server-addr: ${spring.cloud.nacos.config.server-addr}\n            namespace: middleware\n            groupId: SENTINEL_GROUP\n            data-id: ${spring.cloud.sentinel.name}-authority-rules.json\n            rule-type: authority\n        gw-flow:\n          nacos:\n            server-addr: ${spring.cloud.nacos.config.server-addr}\n            namespace: middleware\n            dataId: ${spring.cloud.sentinel.name}-gw-flow-rules.json\n            groupId: SENTINEL_GROUP\n            rule-type: gw-flow\n        gw-api-group:\n          nacos:\n            server-addr: ${spring.cloud.nacos.config.server-addr}\n            namespace: middleware\n            dataId: ${spring.cloud.sentinel.name}-gw-api-group-rules.json\n            groupId: SENTINEL_GROUP\n            rule-type: gw-api-group\n\n    gateway:\n      httpclient:\n        # 建立 TCP 连接的超时时间\n        connect-timeout: 1000\n        # 从连接成功开始，到收到后端完整响应的总超时\n        response-timeout: 30s\n\n      discovery:\n        locator:\n          enabled: true\n\n      default-filters:\n      - StripPrefix=1\n      - name: Retry\n        args:\n          retries: 1\n          methods: \n            - GET\n            - POST\n          statuses: \n            - BAD_GATEWAY\n            - GATEWAY_TIMEOUT\n            - SERVICE_UNAVAILABLE\n          exceptions: \n            - java.net.ConnectException\n            - org.springframework.cloud.gateway.support.NotFoundException\n            - reactor.netty.http.client.PrematureCloseException\n\n\n      routes: \n        - id: MAOZI-CLOUD-SYSTEM\n          uri: lb://maozi-cloud-system-service\n          predicates:\n          - Path=/system/**\n\n        - id: MAOZI-CLOUD-OAUTH\n          uri: lb://maozi-cloud-oauth-service\n          predicates:\n          - Path=/oauth/**\n\n        - id: MAOZI-CLOUD-AI-SERVICE\n          uri: lb://maozi-cloud-ai-service\n          predicates:\n          - Path=/ai/**', '821e0c36ba57f7a57c23ca2158f16365', '2026-07-03 13:54:34', '2026-10-17 22:33:45', NULL, '172.18.0.1', '', 'local', '', '', '', 'yaml', '', '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (5772, 'boot-datasource.yml', 'DEFAULT_GROUP', 'spring:\n  datasource:\n    type: com.zaxxer.hikari.HikariDataSource\n    driver-class-name: com.mysql.cj.jdbc.Driver\n    url: jdbc:mysql://${application-datasource-jdbc-url:maozi-cloud-basic-mysql:3306}/${application-datasource-db-name:${spring.application.name}-${application.environment}-db}?useSSL=false&serverTimezone=Asia/Shanghai&characterEncoding=utf8&nullCatalogMeansCurrent=true\n    username: ${application-datasource-jdbc-username:root}\n    password: ${application-datasource-jdbc-password:password}\n    hikari:\n      # 最大连接，根据业务压测调整，默认推荐10~20，不要直接50\n      maximum-pool-size: 15\n      # 获取连接等待超时时间\n      connection-timeout: 6000\n      # 不配置minimum-idle，Hikari官方推荐，最小空闲连接等于最大连接\n      # minimum-idle: 10\n      # 空闲连接超时，注意必须小于max-lifetime\n      idle-timeout: 300000\n      # 连接最大存活时间，比mysql wait_timeout小至少60s，示例540s=9min\n      max-lifetime: 540000\n      # 删掉 connection-test-query，Hikari用JDBC4 isValid校验', '7cc45b7052b60a30606688ac3bc0c231', '2026-07-03 14:33:55', '2026-10-03 07:22:07', NULL, '192.168.65.1', '', 'dev', '', '', '', 'yaml', '', '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (5773, 'boot-elasticsearch.yml', 'DEFAULT_GROUP', 'spring:\n  data:\n    elasticsearch:\n    ####集群名称\n     cluster-name: maozi-cloud-es\n    ####地址 \n     cluster-nodes: 192.168.0.1,192.168.0.2', '488145c960b14d62df086865f533cc4a', '2026-07-03 14:33:55', '2026-07-03 14:33:55', NULL, '172.18.0.1', '', 'dev', NULL, NULL, NULL, 'yaml', NULL, '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (5775, 'boot-redis.yml', 'DEFAULT_GROUP', 'spring:\n  data:\n    redis:\n      host: ${APPLICATION_REDIS_SERVER:maozi-cloud-basic-redis}\n      port: ${APPLICATION_REDIS_PORT:6379}\n      # 密码从环境变量读取，禁止硬编码\n      password: ${APPLICATION_REDIS_SERVER_PASSWORD:password}\n      database: ${APPLICATION_REDIS_SERVER_DATABASE:0}\n      # 可选，客户端标识，方便redis client list排查\n      client-name: ${spring.application.name}\n      lettuce:\n        # 命令超时，建议500ms，根据业务微调，不要超过1s\n        timeout: 500ms\n        shutdown-timeout: 300ms\n        pool:\n          # 最大活跃连接，根据单实例QPS，一般80~200\n          max-active: 120\n          # 获取连接最大等待时间1s\n          max-wait: 1000ms\n          max-idle: 60\n          # 维持少量预热连接\n          min-idle: 10', '605e5296aff327c8ec986fc9b73888b8', '2026-07-03 14:33:55', '2026-10-03 04:31:36', NULL, '172.18.0.1', '', 'dev', '', '', '', 'yaml', '', '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (5797, 'cloud-default.yml', 'DEFAULT_GROUP', 'server:\n  port: ${APPLICATION_PORT:${application.port:0}}\n  error.path: /application/error\n  # graceful=优雅停机 / immediate=立刻关闭\n  shutdown: graceful\n  undertow:\n    # 单个请求超时时间，单位毫秒\n    request-timeout: 30000\n  # compression:\n  #   enabled: true\n  #   min-response-size: 1024\n  #   mime-types: application/json,application/xml,text/html,text/xml,text/plain\n\nspring:\n  lifecycle:\n    # 优雅停机等待最大超时时间，按需调整，一般10~30s\n    timeout-per-shutdown-phase: 65s\n  main:\n    banner-mode: off\n    log-startup-info: false\n  web:\n    resources:\n      add-mappings: false\n  mvc: \n    throw-exception-if-no-handler-found: true\n    pathmatch.matching-strategy: ant_path_matcher\n  jackson: \n    time-zone: GMT+8\n    date-format: yyyy-MM-dd HH:mm:ss\n    default-property-inclusion: NON_NULL\n\nfeign:\n  sentinel:\n    enabled: true\n  okhttp:\n    enabled: true\n  httpclient:\n    enabled: false\n  client:\n    config:\n      default:\n        connectTimeout: 30000\n        readTimeout: 30000\n  compression:\n    request:\n      # 开启请求数据的压缩功能\n      enabled: true\n      # 最小压缩值标准，当数据大于 1024 才会进行压缩\n      min-request-size: 1024\n      # 压缩类型\n      mime-types: text/xml,application/xml,application/json\n    response:\n      enabled: true\n\nlogging: \n  level: \n    root: ERROR\n    com.maozi: INFO\n    org.apache.dubbo.registry: OFF\n    org.apache.dubbo.remoting: OFF', '182d08f87932cd8e502a511da843ede1', '2026-07-03 14:33:55', '2026-10-12 03:41:12', NULL, '172.18.0.1', '', 'dev', '', '', '', 'yaml', '', '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (5798, 'cloud-dubbo.yml', 'DEFAULT_GROUP', 'dubbo:\n  application: \n    name: dubbo-${spring.application.name}\n    # instance/interface/all\n    register-mode: instance\n    version: ${application.version:main}\n    serialize-check-status: DISABLE\n    check-serializable: false\n  scan:\n    base-packages: com.maozi.${application-project-abbreviation}.*.api.impl.rpc\n  protocol:\n    # name: tri\n    name: dubbo\n    port: ${APPLICATION_DUBBO_PORT:${application.dubbo.port:-1}}\n  provider:\n    timeout: 30000\n    filter: applicationDubboContextLoadFilter\n    prefer-serialization: hessian2\n    serialization: hessian2\n  consumer:\n    check: false\n    timeout: 30000\n    retries: 1\n    filter: applicationDubboContextTransmitFilter\n  registry:\n    address: nacos://${spring.cloud.nacos.discovery.server-addr}?namespace=${spring.cloud.nacos.discovery.namespace}', '36d95bd74966ab9c9179e3653a96702f', '2026-07-03 14:33:55', '2026-10-17 15:09:39', NULL, '172.18.0.1', '', 'dev', '', '', '', 'yaml', '', '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (5799, 'cloud-nacos.yml', 'DEFAULT_GROUP', 'spring: \n  cloud: \n    nacos: \n      discovery:\n        enabled: true\n        register-enabled: true\n        metadata: \n          version: ${application.version:main}', 'fd1de2e137ce9e9b7f35977c32d444fd', '2026-07-03 14:33:55', '2026-09-07 11:17:15', 'nacos', '192.168.65.1', '', 'dev', '', '', '', 'yaml', '', '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (5800, 'cloud-rocket.yml', 'DEFAULT_GROUP', 'spring:\n  cloud:\n    stream:\n      rocketmq:\n        binder:\n          # access-key: \n          # secret-key: \n          name-server: localhost:9876\n# rocketmq:\n  # instance:\n    # id: \n    # name: ', 'e01da9f5d2b141a256fb4baa9e8c32b3', '2026-07-03 14:33:55', '2026-07-03 14:33:55', NULL, '172.18.0.1', '', 'dev', '', NULL, NULL, 'yaml', NULL, '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (5801, 'cloud-sentinel.yml', 'DEFAULT_GROUP', 'resttemplate:\n  sentinel:\n    enabled: true\n\nfeign:\n  sentinel: \n    enabled: true\n\nspring: \n  cloud: \n    sentinel:\n      name: ${spring.application.name}-${application.environment:local}-${application.version:main}\n      eager: true\n      transport:\n        port: 8719\n        dashboard: ${APPLICATION_SENTINEL_SERVER:maozi-cloud-basic-sentinel:8858}\n      http-method-specify: true\n      datasource:\n        flow:\n          nacos:\n            server-addr: ${spring.cloud.nacos.config.server-addr}\n            namespace: middleware\n            groupId: SENTINEL_GROUP\n            dataId: ${spring.cloud.sentinel.name}-flow-rules.json\n            rule-type: flow\n        degrade:\n          nacos:\n            server-addr: ${spring.cloud.nacos.config.server-addr}\n            namespace: middleware\n            groupId: SENTINEL_GROUP\n            dataId: ${spring.cloud.sentinel.name}-degrade-rules.json\n            rule-type: degrade\n        param-flow:\n          nacos:\n            server-addr: ${spring.cloud.nacos.config.server-addr}\n            namespace: middleware\n            groupId: SENTINEL_GROUP\n            dataId: ${spring.cloud.sentinel.name}-param-rules.json\n            rule-type: param-flow\n        system:\n          nacos:\n            server-addr: ${spring.cloud.nacos.config.server-addr}\n            namespace: middleware\n            groupId: SENTINEL_GROUP\n            dataId: ${spring.cloud.sentinel.name}-system-rules.json\n            rule-type: system\n        authority:\n          nacos:\n            server-addr: ${spring.cloud.nacos.config.server-addr}\n            namespace: middleware\n            groupId: SENTINEL_GROUP\n            data-id: ${spring.cloud.sentinel.name}-authority-rules.json\n            rule-type: authority', '334c7c3b92af00bdd2fa0b1dd5267d5b', '2026-07-03 14:33:55', '2026-10-17 14:50:14', NULL, '172.18.0.1', '', 'dev', '', '', '', 'yaml', '', '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (5863, 'saas-param-error.json', 'DEFAULT_GROUP', '{\n    \"orderId\":\"订单\",\n    \"memberId\":\"客户\",\n    \"promoteId\":\"推广\",\n    \"day\":\"天数\",\n    \"labelId\":\"标签\",\n    \"userId\":\"用户\",\n    \"username\":\"用户名\",\n    \"password\":\"密码\",\n    \"messageId\":\"消息\",\n    \"roleId\":\"角色\",\n    \"compareCredentialsImage\":\"比价凭证\",\n    \"orderValuationId\":\"报价单\",\n    \"assessorAmount\":\"报价价格\",\n    \"storesId\":\"门店\",\n    \"city\":\"城市\",\n    \"query\":\"关键字\",\n    \"region\":\"城市\"\n}', '57ddd9c3a95d95c80023360aa916a225', '2026-07-03 14:33:55', '2026-07-03 14:33:55', NULL, '172.18.0.1', '', 'dev', NULL, NULL, NULL, 'json', NULL, '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (5864, 'boot-arthas.yml', 'DEFAULT_GROUP', 'arthas: \n  agent-id: ${spring.application.name}\n  tunnel-server: ws://localhost:7777/ws\n  telnet-port: -1\n  http-port: -1', '643c917b51311cefa55fb225a7b0cb2b', '2026-07-03 14:33:55', '2026-07-03 14:33:55', NULL, '172.18.0.1', '', 'dev', '', NULL, NULL, 'yaml', NULL, '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (5865, 'boot-lock.yml', 'DEFAULT_GROUP', 'lock:\n  redisson:\n    address: redis://${spring.data.redis.host}:${spring.data.redis.port}\n    password: ${spring.data.redis.password}\n    database: ${spring.data.redis.database:0}\n    # waitTime: 60 #获取锁最长阻塞时间（默认：60，单位：秒）\n    # leaseTime: 60 #已获取锁后自动释放时间（默认：60，单位：秒）\n    # redis集群配置 如 redis://127.0.0.1:7000,redis://127.0.0.1:7001,redis://127.0.0.1:7002\n    # spring.klock.address 和 spring.klock.cluster-server.node-addresses 选其一即可\n    # cluster-server.node-addresses:', 'd037294dcbda68b36486a37f57f7d1ef', '2026-07-03 14:33:55', '2026-07-15 15:47:09', 'nacos', '172.18.0.1', '', 'dev', '', '', '', 'yaml', '', '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (5866, 'boot-monitor.yml', 'DEFAULT_GROUP', 'spring:  \n  boot: \n    admin: \n      client:\n        url: http://${APPLICATION_MONITOR_SERVER:maozi-cloud-basic-monitor:2000}\n        username: admin\n        password: admin\n        auto-deregistration: true\n        instance: \n          prefer-ip: true\n          metadata: \n            version: 环境:${application.environment:local} 版本:${application.version:main}\n            tags: \n              environment: ${application.environment:local}\n              version: ${application.version:main}\n\nendpoints:\n  dubbo:\n    enabled: true\n\nmanagement:\n  info.env.enabled: true\n  health:\n    dubbo:\n      status:\n        defaults: memory\n        extras: load,threadpool\n  endpoints:\n    web:\n      exposure:\n        include: \'*\'\n  endpoint:\n    serviceregistry:\n      enabled: true\n    shutdown:\n      enabled: true\n    dubbo:\n      enabled: true\n    dubbo-shutdown:\n      enabled: true\n    dubbo-configs:\n      enabled: true\n    dubbo-services:\n      enabled: true\n    dubbo-references:\n      enabled: true\n    dubbo-properties:\n      enabled: true\n    health:\n      show-details: ALWAYS\n      probes.enabled: true\n  metrics:\n    tags:\n      application: ${spring.application.name}\n      instances: ${spring.cloud.client.ip-address}\n      environment: ${application.environment}\n    distribution:\n      percentiles-histogram:\n        http:\n          server:\n            requests: \'true\'\n  observations: \n    key-values: \n      application: ${spring.application.name}\n      instances: ${spring.cloud.client.ip-address}\n      environment: ${application.environment}', 'c31c3a146c6d3b31f5fc48bf121a8ed4', '2026-07-03 14:33:55', '2026-10-17 05:03:39', NULL, '172.18.0.1', '', 'dev', '', '', '', 'yaml', '', '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (5867, 'cloud-oauth.yml', 'DEFAULT_GROUP', 'spring:\n  security:\n    oauth2:\n      resourceserver:\n        opaquetoken:\n          # http 或 rpc\n          # mode: http\n          # 客户端id\n          client-id: system\n          # 客户端秘钥\n          client-secret: 123456', '77e5f1492fd39d65cead251a27a4abea', '2026-07-03 14:33:55', '2026-07-08 20:33:31', 'nacos', '172.18.0.1', '', 'dev', '', '', '', 'yaml', '', '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (5868, 'boot-db.yml', 'DEFAULT_GROUP', 'mybatis-plus:\n  mapper-locations: classpath:com/maozi/${application-project-abbreviation}/*/mapper/*.xml\n  # typeEnumsPackage: com.maozi.${application-project-abbreviation}.*.enums\n  configuration: \n    map-underscore-to-camel-case: true\n    log-impl: com.maozi.db.config.MybatisPlusLog\n    default-enum-type-handler: com.baomidou.mybatisplus.core.handlers.MybatisEnumTypeHandler\n    # log-impl: org.apache.ibatis.logging.stdout.StdOutImpl\n  global-config: \n    refresh: false\n    banner: false\n    db-config:\n      db-type: mysql\n      id-type: AUTO\n      field-strategy: NOT_NULL\n      column-like: false\n      capital-mode: true\n      logic-delete-value: 1\n      logic-not-delete-value: 0\n\nmybatis-plus-join:\n  banner: false\n  table-alias: main\n\nmybatis:\n  configuration:\n    cache-enabled: false\n\nspring: \n  flyway: \n    enabled: true\n    table: system_table_flyway\n    clean-disabled: true\n    out-of-order: true\n    baseline-on-migrate: true\n    baseline-version: 0\n    locations: classpath:db\n    encoding: UTF-8', '6b82a3996631502d935dd3831737dd42', '2026-07-03 14:33:55', '2026-07-03 14:33:55', NULL, '172.18.0.1', '', 'dev', '', NULL, NULL, 'yaml', NULL, '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (5869, 'maozi-cloud-system-service.yml', 'DEFAULT_GROUP', 'application:\n  title: 系统服务\n  details: 管理 用户、角色、权限、系统配置 等功能\n\n# application-datasource-jdbc-url: localhost:3306/maozi-cloud-test-db\n# application-datasource-jdbc-username: root\n# application-datasource-jdbc-password: password\n# application-datasource-db-name: maozi-cloud-system-dev-db\n\napplication-project-whitelist: /config/system/get\n\napplication-project-system:\n  projectName: 小猫子脚手架\n  corporationName: 小猫子网络科技有限公司\n  icon: http://dummyimage.com/100x100\n  environment: ${application.environment}\n  description: 基于 Spring Cloud Alibaba + Dubbo 的一站式分布式解决方案开源封装，内置分布式应用开发所需全套组件，统一团队代码风格，保障代码质量，让开发者专注业务逻辑，实现高效快速开发。\n  copyright: 本网站所有权归《${application-project-system.corporationName}》所有，请勿抄袭和抄袭\n\nspring.servlet.multipart: \n  # 上传大小限制（默认仅 1MB）\n  max-file-size: 1MB\n  \noss:\n  # 路由到阿里云处理器\n  store-type: aliyun\n  aliyun:\n    access-key-id: ${APPLICATION_ALIYUN_CLIENT_ID}\n    access-key-secret: ${APPLICATION_ALIYUN_CLIENT_SECRET}\n    region: cn-beijing\n    endpoint: https://oss-cn-beijing.aliyuncs.com\n    bucket: maozi-cloud-bucket\n    #domain:                  # 可选，CDN 自定义域名', 'f2a7bfef282b4f1d89ca1893e79130b1', '2026-07-03 14:33:55', '2026-09-19 21:04:04', 'nacos', '192.168.65.1', '', 'dev', '', '', '', 'yaml', '', '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (5870, 'maozi-cloud-oauth-service.yml', 'DEFAULT_GROUP', 'application:\n  title: 认证授权服务\n  details: 管理 三方认证授权、客户端 等功能\n\n# application-datasource-jdbc-url: localhost:3306/maozi-cloud-test-db\n# application-datasource-jdbc-username: root\n# application-datasource-jdbc-password: password\n\n# application-datasource-db-name: maozi-cloud-oauth-dev-db\n\n# application-project-whitelist: ', '03300988ea153ae9f934cdc06f9f5bbf', '2026-07-03 14:33:55', '2026-09-07 09:53:06', 'nacos', '192.168.65.1', '', 'dev', '', '', '', 'yaml', '', '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (5871, 'maozi-cloud-gateway-service.yml', 'DEFAULT_GROUP', 'application:\n  port: 1100\n  title: 网关服务\n  details: 处理 流量分发、黑白名单、流控 等功能\n\nspring: \n  cloud:\n    sentinel:\n      name: ${spring.application.name}-${application.environment:local}-${application.version:main}\n      eager: true\n      transport:\n        port: 8719\n        dashboard: ${APPLICATION_SENTINEL_SERVER:maozi-cloud-basic-sentinel:8858}\n      filter:\n        enabled: false\n      datasource:\n        flow:\n          nacos:\n            server-addr: ${spring.cloud.nacos.config.server-addr}\n            namespace: middleware\n            groupId: SENTINEL_GROUP\n            dataId: ${spring.cloud.sentinel.name}-flow-rules.json\n            rule-type: flow\n        degrade:\n          nacos:\n            server-addr: ${spring.cloud.nacos.config.server-addr}\n            namespace: middleware\n            groupId: SENTINEL_GROUP\n            dataId: ${spring.cloud.sentinel.name}-degrade-rules.json\n            rule-type: degrade\n        param-flow:\n          nacos:\n            server-addr: ${spring.cloud.nacos.config.server-addr}\n            namespace: middleware\n            groupId: SENTINEL_GROUP\n            dataId: ${spring.cloud.sentinel.name}-param-rules.json\n            rule-type: param-flow\n        system:\n          nacos:\n            server-addr: ${spring.cloud.nacos.config.server-addr}\n            namespace: middleware\n            groupId: SENTINEL_GROUP\n            dataId: ${spring.cloud.sentinel.name}-system-rules.json\n            rule-type: system\n        authority:\n          nacos:\n            server-addr: ${spring.cloud.nacos.config.server-addr}\n            namespace: middleware\n            groupId: SENTINEL_GROUP\n            data-id: ${spring.cloud.sentinel.name}-authority-rules.json\n            rule-type: authority\n        gw-flow:\n          nacos:\n            server-addr: ${spring.cloud.nacos.config.server-addr}\n            namespace: middleware\n            dataId: ${spring.cloud.sentinel.name}-gw-flow-rules.json\n            groupId: SENTINEL_GROUP\n            rule-type: gw-flow\n        gw-api-group:\n          nacos:\n            server-addr: ${spring.cloud.nacos.config.server-addr}\n            namespace: middleware\n            dataId: ${spring.cloud.sentinel.name}-gw-api-group-rules.json\n            groupId: SENTINEL_GROUP\n            rule-type: gw-api-group\n\n    gateway:\n      httpclient:\n        # 建立 TCP 连接的超时时间\n        connect-timeout: 1000\n        # 从连接成功开始，到收到后端完整响应的总超时\n        response-timeout: 30s\n\n      discovery:\n        locator:\n          enabled: true\n\n      default-filters:\n      - StripPrefix=1\n      - name: Retry\n        args:\n          retries: 1\n          methods: \n            - GET\n            - POST\n          statuses: \n            - BAD_GATEWAY\n            - GATEWAY_TIMEOUT\n            - SERVICE_UNAVAILABLE\n          exceptions: \n            - java.net.ConnectException\n            - org.springframework.cloud.gateway.support.NotFoundException\n            - reactor.netty.http.client.PrematureCloseException\n\n\n      routes: \n        - id: MAOZI-CLOUD-SYSTEM\n          uri: lb://maozi-cloud-system-service\n          predicates:\n          - Path=/system/**\n\n        - id: MAOZI-CLOUD-OAUTH\n          uri: lb://maozi-cloud-oauth-service\n          predicates:\n          - Path=/oauth/**\n\n        - id: MAOZI-CLOUD-AI-SERVICE\n          uri: lb://maozi-cloud-ai-service\n          predicates:\n          - Path=/ai/**', '821e0c36ba57f7a57c23ca2158f16365', '2026-07-03 14:33:55', '2026-10-17 22:33:24', NULL, '172.18.0.1', '', 'dev', '', '', '', 'yaml', '', '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (6375, 'cloud-seata.yml', 'DEFAULT_GROUP', 'seata:\n  enabled: true\n  application-id: ${spring.application.name}\n  tx-service-group: maozi-cloud-${application.environment}-tx-group\n  config:\n    type: nacos\n    nacos:\n      serverAddr: ${spring.cloud.nacos.config.server-addr}\n      namespace: middleware\n      group: SEATA_GROUP\n      dataId: seata.properties\n      username: \'nacos\'\n      password: \'nacos\'\n  registry:\n    type: nacos\n    nacos:\n      application: maozi-cloud-basic-seata\n      server-addr: ${spring.cloud.nacos.discovery.server-addr}\n      namespace: middleware\n      group: SEATA_GROUP\n      username: \'nacos\'\n      password: \'nacos\'', '416b1f64ed5502aa34bb554242290f4e', '2026-07-13 11:51:00', '2026-09-07 11:18:27', 'nacos', '192.168.65.1', '', 'local', '', '', '', 'yaml', '', '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (6377, 'seata.properties', 'SEATA_GROUP', 'store.mode=db\n#-----db-----\nstore.db.datasource=druid\nstore.db.dbType=mysql\n# 需要根据mysql的版本调整driverClassName\n# mysql8及以上版本对应的driver：com.mysql.cj.jdbc.Driver\n# mysql8以下版本的driver：com.mysql.jdbc.Driver\nstore.db.driverClassName=com.mysql.cj.jdbc.Driver\nstore.db.url=jdbc:mysql://maozi-cloud-basic-mysql:3306/maozi-cloud-seata-middleware-db?useUnicode=true&characterEncoding=utf8&connectTimeout=1000&socketTimeout=3000&autoReconnect=true&useSSL=false\nstore.db.user=root\nstore.db.password=password\n# 数据库初始连接数\nstore.db.minConn=1\n# 数据库最大连接数\nstore.db.maxConn=20\n# 获取连接时最大等待时间 默认5000，单位毫秒\nstore.db.maxWait=5000\n# 全局事务表名 默认global_table\nstore.db.globalTable=global_table\n# 分支事务表名 默认branch_table\nstore.db.branchTable=branch_table\n# 全局锁表名 默认lock_table\nstore.db.lockTable=lock_table\n# 查询全局事务一次的最大条数 默认100\nstore.db.queryLimit=100\n\n\nservice.vgroupMapping.maozi-cloud-local-tx-group=default\nservice.vgroupMapping.maozi-cloud-dev-tx-group=default\n# undo保留天数 默认7天,log_status=1（附录3）和未正常清理的undo\nserver.undo.logSaveDays=7\n# undo清理线程间隔时间 默认86400000，单位毫秒\nserver.undo.logDeletePeriod=86400000\n# 二阶段提交重试超时时长 单位ms,s,m,h,d,对应毫秒,秒,分,小时,天,默认毫秒。默认值-1表示无限重试\n# 公式: timeout>=now-globalTransactionBeginTime,true表示超时则不再重试\n# 注: 达到超时时间后将不会做任何重试,有数据不一致风险,除非业务自行可校准数据,否者慎用\nserver.maxCommitRetryTimeout=-1\n# 二阶段回滚重试超时时长\nserver.maxRollbackRetryTimeout=-1\n# 二阶段提交未完成状态全局事务重试提交线程间隔时间 默认1000，单位毫秒\nserver.recovery.committingRetryPeriod=1000\n# 二阶段异步提交状态重试提交线程间隔时间 默认1000，单位毫秒\nserver.recovery.asynCommittingRetryPeriod=1000\n# 二阶段回滚状态重试回滚线程间隔时间  默认1000，单位毫秒\nserver.recovery.rollbackingRetryPeriod=1000\n# 超时状态检测重试线程间隔时间 默认1000，单位毫秒，检测出超时将全局事务置入回滚会话管理器\nserver.recovery.timeoutRetryPeriod=1000', '4b7b25641b6faad14098d7e7eb663fd2', '2026-07-13 12:01:58', '2026-07-14 22:31:30', 'nacos', '172.18.0.1', '', 'middleware', '', '', '', 'properties', '', '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (6446, 'cloud-seata.yml', 'DEFAULT_GROUP', 'seata:\n  enabled: true\n  application-id: ${spring.application.name}\n  tx-service-group: maozi-cloud-${application.environment}-tx-group\n  config:\n    type: nacos\n    nacos:\n      serverAddr: ${spring.cloud.nacos.config.server-addr}\n      namespace: middleware\n      group: SEATA_GROUP\n      dataId: seata.properties\n      username: \'nacos\'\n      password: \'nacos\'\n  registry:\n    type: nacos\n    nacos:\n      application: maozi-cloud-basic-seata\n      server-addr: ${spring.cloud.nacos.discovery.server-addr}\n      namespace: middleware\n      group: SEATA_GROUP\n      username: \'nacos\'\n      password: \'nacos\'', '416b1f64ed5502aa34bb554242290f4e', '2026-07-15 15:45:15', '2026-09-07 11:19:03', 'nacos', '192.168.65.1', '', 'dev', '', '', '', 'yaml', '', '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (6836, 'maozi-cloud-ai-service.yml', 'DEFAULT_GROUP', 'application:\n  title: AI服务\n  details: 与AI交互、管理AI对话记忆、AI知识库、AI提示词等\n\n# application-datasource-jdbc-url: localhost:3306/maozi-cloud-test-db\n# application-datasource-jdbc-username: root\n# application-datasource-jdbc-password: password\n# application-datasource-db-name: maozi-cloud-system-local-db\n\nspring: \n  ai: \n    # zhipuai: \n    #   base-url: https://api.z.ai/api/paas\n    #   api-key: \n    #   chat:\n    #     options:\n    #       model: glm-5.2\n    #   embedding:\n    #     enabled: false\n    dashscope: \n      api-key: ${APPLICATION_AI_DASHSCOPE_KEY}\n      chat: \n        enabled: true\n        options: \n          model: qwen-max\n          text_image_model: qwen-vl-max\n      embedding: \n        enabled: false\n        options: \n          model: text-embedding-v3\n          dimensions: 1024\n    # openai: \n    #   base-url: \n    #   api-key: \n    #   chat: \n    #     options: \n    #       model: gpt\n    #   embedding:\n    #     enabled: false', '9fc27916e312121c29e8fdae9a43d848', '2026-08-15 19:47:49', '2026-09-19 21:03:10', 'nacos', '192.168.65.1', '', 'local', '', '', '', 'yaml', '', '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (7027, 'maozi-cloud-ai-service.yml', 'DEFAULT_GROUP', 'application:\n  title: AI服务\n  details: 与AI交互、管理AI对话记忆、AI知识库、AI提示词等\n\n# application-datasource-jdbc-url: localhost:3306/maozi-cloud-test-db\n# application-datasource-jdbc-username: root\n# application-datasource-jdbc-password: password\n# application-datasource-db-name: maozi-cloud-system-local-db\n\nspring: \n  ai: \n    # zhipuai: \n    #   base-url: https://api.z.ai/api/paas\n    #   api-key: \n    #   chat:\n    #     options:\n    #       model: glm-5.2\n    #   embedding:\n    #     enabled: false\n    dashscope: \n      api-key: ${APPLICATION_AI_DASHSCOPE_KEY}\n      chat: \n        enabled: true\n        options: \n          model: qwen-max\n          text_image_model: qwen-vl-max\n      embedding: \n        enabled: false\n        options: \n          model: text-embedding-v3\n          dimensions: 1024\n    # openai: \n    #   base-url: \n    #   api-key: \n    #   chat: \n    #     options: \n    #       model: gpt\n    #   embedding:\n    #     enabled: false', '9fc27916e312121c29e8fdae9a43d848', '2026-08-21 08:04:30', '2026-09-19 21:03:39', 'nacos', '192.168.65.1', '', 'dev', '', '', '', 'yaml', '', '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (7485, 'boot-snailjob.yml', 'DEFAULT_GROUP', 'snail-job:\n  # 任务调度服务器信息\n  server:\n    # 服务器IP地址（或域名）；集群时建议通过 nginx 做负载均衡\n    host: ${SNAIL_JOB_SERVER:maozi-cloud-basic-snailjob}\n    # 服务器通讯端口（不是后台管理页面服务端口）\n    port: 17888\n  # 命名空间 【上面配置的空间的唯一标识】\n  namespace: ${application.environment}\n  # 接入组名【上面配置的组名称】注意: 若通过注解配置了这里的配置不生效\n  group: ${spring.application.name}-${application.version:main}\n  # 接入组 token 【上面配置的token信息】\n  token: SJ_Wyz3dmsdbDOkDujOTSSoBjGQP1BMsVnj\n  # 客户端绑定IP，必须服务器可以访问到；默认自动推断，在服务器无法调度客户端时需要手动配置\n#   host: 127.0.0.1\n  # 客户端通讯端口，默认 17889\n  port: 17889\n\n  labels:\n    version: ${application.version:main}', '67bef13018518276857de5d64a035deb', '2026-09-02 18:23:48', '2026-09-28 17:29:32', NULL, '172.18.0.1', '', 'local', '', '', '', 'yaml', '', '');
